"architecture":[
{
"id":"data_extract_store",
"name":"数据提取与存储",
"responsibility":"登记来源、频率、日期范围和可见性边界，并形成统一数据包。",
"input":[
"行情接口或本地文件",
"资产池",
"日期范围"
],
"output":[
"统一数据包",
"数据清单",
"数据指纹"
],
"controls":[
"来源可追踪",
"日期边界",
"不保存凭证"
],
"status":"completed"
},
{
"id":"single_factor_research",
"name":"单个因子挖掘与测试",
"responsibility":"单独定义因子、方向、观察窗口、滞后和 forward return，再评估 IC、分组和覆盖度。",
"input":[
"数据包",
"因子定义",
"训练集 / 验证集 / 留出集"
],
"output":[
"因子值表",
"IC / 分组收益",
"衰减和换手证据"
],
"controls":[
"信号至少滞后 1 期",
"预测周期明确",
"时间切分"
],
"status":"completed"
},
{
"id":"factor_improvement",
"name":"因子改进与综合",
"responsibility":"把经过单因子测试的信号做标准化、方向统一和加权合成，记录每个权重的来源。",
"input":[
"单因子评估结果",
"标准化规则",
"权重方案"
],
"output":[
"composite_v1 因子",
"权重快照",
"对比结果"
],
"controls":[
"权重和为 1",
"横截面正交化",
"不使用留出集调参",
"版本化"
],
"status":"completed"
},
{
"id":"risk_rebalance",
"name":"风控与调仓逻辑",
"responsibility":"把目标权重变成受约束的执行权重，并统一处理调仓频率、换手和交易成本。",
"input":[
"目标权重",
"持仓状态",
"成本配置",
"风险约束"
],
"output":[
"执行权重",
"换手",
"成本",
"风险事件"
],
"controls":[
"只做多",
"总敞口 ≤ 1",
"买入与卖出费率"
],
"status":"completed"
},
{
"id":"strategy_iteration",
"name":"策略设计与迭代",
"responsibility":"比较基准、单因子和综合因子，把假设、改动和决策原因写进迭代记录。",
"input":[
"因子证据",
"策略规则",
"训练 / 验证结果"
],
"output":[
"候选策略表",
"迭代记录",
"待验证假设"
],
"controls":[
"先训练 / 验证",
"留出集不参与调参",
"保留失败版本"
],
"status":"completed"
},
{
"id":"backtest_report",
"name":"回测与报告产出",
"responsibility":"按时间顺序执行信号、滞后、收益和成本，产出可复核的净值、持仓和绩效报告。",
"input":[
"回测配置",
"目标权重",
"资产收益",
"交易成本模型"
],
"output":[
"净值",
"持仓轨迹",
"指标",
"报告摘要"
],
"controls":[
"2019-01-31 → 2025-12-31",
"信号滞后 = 1 期",
"统一交易成本模型"
],
"status":"completed"
},
{
"id":"version_record",
"name":"版本管理与运行记录",
"responsibility":"将代码、配置、数据、策略参数和产物绑定成可重放的研究版本。",
"input":[
"各阶段清单",
"配置快照",
"代码版本"
],
"output":[
"运行清单",
"产物指纹",
"版本 / 迭代日志"
],
"controls":[
"不可覆盖运行 ID",
"输入输出可追溯",
"脱敏发布"
],
"status":"completed"
}
],
